<?php
$pageTitle='Staff & Attendance'; require __DIR__.'/staff_common.php';
if(isset($_POST['action'])){
  try{
    if($_POST['action']==='save_staff'){
      $id=(int)($_POST['id']??0); $data=[trim($_POST['employee_code']),trim($_POST['name']),trim($_POST['phone']),trim($_POST['position']),$_POST['join_date']?:null,(float)$_POST['basic_salary'],(float)$_POST['allowance'],(float)$_POST['deduction'],(int)$_POST['weekly_off_day']];
      if($id){$st=$pdo->prepare('UPDATE staff SET employee_code=?,name=?,phone=?,position=?,join_date=?,basic_salary=?,allowance=?,deduction=?,weekly_off_day=? WHERE id=?');$st->execute([...$data,$id]);}
      else{$st=$pdo->prepare('INSERT INTO staff(employee_code,name,phone,position,join_date,basic_salary,allowance,deduction,weekly_off_day) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute($data);}
    } elseif($_POST['action']==='delete_staff'){ $pdo->prepare('DELETE FROM staff WHERE id=?')->execute([(int)$_POST['id']]); }
    elseif($_POST['action']==='save_attendance'){ $st=$pdo->prepare("INSERT INTO staff_attendance(staff_id,attendance_date,status,notes) VALUES(?,?,?,?) ON CONFLICT(staff_id,attendance_date) DO UPDATE SET status=excluded.status, notes=excluded.notes"); if(defined('DB_DRIVER')&&DB_DRIVER==='mysql') $st=$pdo->prepare("INSERT INTO staff_attendance(staff_id,attendance_date,status,notes) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status), notes=VALUES(notes)"); $st->execute([(int)$_POST['staff_id'],$_POST['date'],$_POST['status'],trim($_POST['notes'])]); }
    elseif($_POST['action']==='save_holiday'){ $st=$pdo->prepare("INSERT INTO staff_holidays(holiday_date,holiday_name,paid) VALUES(?,?,?) ON CONFLICT(holiday_date) DO UPDATE SET holiday_name=excluded.holiday_name,paid=excluded.paid"); if(defined('DB_DRIVER')&&DB_DRIVER==='mysql') $st=$pdo->prepare("INSERT INTO staff_holidays(holiday_date,holiday_name,paid) VALUES(?,?,?) ON DUPLICATE KEY UPDATE holiday_name=VALUES(holiday_name),paid=VALUES(paid)"); $st->execute([$_POST['holiday_date'],trim($_POST['holiday_name']),isset($_POST['paid'])?1:0]); }
    elseif($_POST['action']==='save_leave'){ $st=$pdo->prepare("INSERT INTO staff_leave(staff_id,leave_date,leave_type,paid,notes) VALUES(?,?,?,?,?) ON CONFLICT(staff_id,leave_date) DO UPDATE SET leave_type=excluded.leave_type,paid=excluded.paid,notes=excluded.notes"); if(defined('DB_DRIVER')&&DB_DRIVER==='mysql') $st=$pdo->prepare("INSERT INTO staff_leave(staff_id,leave_date,leave_type,paid,notes) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE leave_type=VALUES(leave_type),paid=VALUES(paid),notes=VALUES(notes)"); $st->execute([(int)$_POST['staff_id'],$_POST['leave_date'],trim($_POST['leave_type']),isset($_POST['paid'])?1:0,trim($_POST['notes'])]); }
    header('Location: staff.php?ok=1'); exit;
  }catch(Throwable $e){$error=$e->getMessage();}
}
$staff=$pdo->query('SELECT * FROM staff WHERE active=1 ORDER BY name')->fetchAll(PDO::FETCH_ASSOC); $month=$_GET['month']??date('Y-m');
include __DIR__.'/includes/header.php';
?>
