<div class="card"><h2>Daily Attendance</h2><form method="post"><input type="hidden" name="action" value="save_attendance"><div class="form-grid"><select name="staff_id" required><option value="">Select staff</option><?php foreach($staff as $s):?><option value="<?=$s['id']?>"><?=h($s['employee_code'].' - '.$s['name'])?></option><?php endforeach;?></select><input type="date" name="date" value="<?=date('Y-m-d')?>"><select name="status"><option>Present</option><option>Absent</option><option>Off Day</option><option>Leave</option><option>Holiday</option></select><input name="notes" placeholder="Notes"></div><button class="btn btn-accent">Save Attendance</button></form><hr><h3>Leave</h3><form method="post"><input type="hidden" name="action" value="save_leave"><div class="form-grid"><select name="staff_id" required><?php foreach($staff as $s):?><option value="<?=$s['id']?>"><?=h($s['name'])?></option><?php endforeach;?></select><input type="date" name="leave_date"><input name="leave_type" value="Annual Leave"><label><input type="checkbox" name="paid" checked> Paid Leave</label><input name="notes" placeholder="Notes"></div><button class="btn">Save Leave</button></form></div>
</div>
<div class="card"><h2>Public / Hotel Holidays</h2><form method="post" style="display:flex;gap:10px;flex-wrap:wrap"><input type="hidden" name="action" value="save_holiday"><input type="date" name="holiday_date" required><input name="holiday_name" placeholder="Holiday name" required><label><input type="checkbox" name="paid" checked> Paid</label><button class="btn">Save Holiday</button></form></div>
